(function () {
  "use strict";
  var KEY = "kabaman.gestion.v1";
  var pageNames = { dashboard:"Vue d’ensemble", calculator:"Calcul des coûts", catalog:"Produits & stock", invoices:"Factures", sales:"Ventes", analytics:"Rentabilité", settings:"Paramètres" };
  function uid(){ return "k"+Date.now().toString(36)+Math.random().toString(36).slice(2,7); }
  function today(){ var d=new Date(); return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0"); }
  function defaults(){ return {
    settings:{wholesaleMarkup:30,retailMarkup:50,customsRate:.5,bankRate:2.5,casnosMonthly:2000,taxFixedMonthly:1700,taxActivityRate:1,eurToDzd:280,stockAlert:5,companyName:"KABAMAN",activity:"Micro-importation • Commerce • Livraison",address:"",phone:"",email:"",nif:"",rc:"",nis:""},
    products:[],sales:[],invoices:[],calcMode:"multi",
    multi:{flight:0,visa:0,hotel:0,transport:0,casnosShare:100,activity:"Non",monthlyRevenue:0,taxShare:100,customsRate:null,bankRate:null,wholesaleMarkup:null,retailMarkup:null,lines:[{reference:"",name:"",quantity:"",buyPrice:"",currency:"DA"}]},
    single:{reference:"",name:"",quantity:1,buyPrice:0,currency:"DA",flight:0,visa:0,hotel:0,transport:0,casnosShare:100,activity:"Non",monthlyRevenue:0,taxShare:100,customsBase:null,customsRate:null,bankBase:null,bankRate:null,wholesaleMarkup:null,retailMarkup:null},
    draft:null,saleDraft:{date:today(),productId:"",quantity:1,priceMode:"Détail",customPrice:"",client:"",invoiceNo:"",paymentStatus:"Payé",paymentMethod:"Espèces"},analyticsPeriod:"month"
  }; }
  function normalize(raw){
    var s=defaults(); if(!raw||typeof raw!=="object")return s;
    if(raw.settings)Object.assign(s.settings,raw.settings);
    ["products","sales","invoices"].forEach(function(k){if(Array.isArray(raw[k]))s[k]=raw[k];});
    if(raw.calcMode==="single"||raw.calcMode==="multi")s.calcMode=raw.calcMode;
    if(raw.multi)Object.assign(s.multi,raw.multi); if(!Array.isArray(s.multi.lines)||!s.multi.lines.length)s.multi.lines=[{reference:"",name:"",quantity:"",buyPrice:"",currency:"DA"}];
    if(raw.single)Object.assign(s.single,raw.single);
    if(raw.draft)s.draft=raw.draft;
    if(raw.saleDraft)Object.assign(s.saleDraft,raw.saleDraft);
    if(raw.analyticsPeriod)s.analyticsPeriod=raw.analyticsPeriod;
    ["activePage","catalogSearch","salesSearch","salesStatusFilter"].forEach(function(k){if(raw[k])s[k]=raw[k];});
    return s;
  }
  function load(){try{return normalize(JSON.parse(localStorage.getItem(KEY)||"null"));}catch(e){return defaults();}}
  var S=load();
  function save(){try{localStorage.setItem(KEY,JSON.stringify(S));}catch(e){toast("Stockage plein. Télécharge une sauvegarde.",true);}}
  function n(v){if(typeof v==="number")return isFinite(v)?v:0;var x=parseFloat(String(v==null?"":v).replace(/\s/g,"").replace(",", "."));return isFinite(x)?x:0;}
  function fmt(v,d){try{return new Intl.NumberFormat("fr-FR",{maximumFractionDigits:d==null?0:d}).format(n(v));}catch(e){return String(Math.round(n(v)));}}
  function money(v){return fmt(v)+" DA";}
  function dateFmt(v){if(!v)return "—";var d=new Date(v+"T12:00:00");try{return new Intl.DateTimeFormat("fr-FR",{day:"2-digit",month:"short",year:"numeric"}).format(d);}catch(e){return v;}}
  function esc(v){return String(v==null?"":v).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c];});}
  function el(id){return document.getElementById(id);}
  function text(id,v){if(el(id))el(id).textContent=v;}
  function toast(msg,error){var t=el("toast");if(!t)return;t.textContent=msg;t.className="toast show"+(error?" error":"");clearTimeout(toast.timer);toast.timer=setTimeout(function(){t.className="toast";},2800);}
  function moneyField(label,path,val,suffix,step,min){return '<div class="field"><label>'+esc(label)+'</label><div class="input-wrap"><input class="input" type="number" inputmode="decimal" data-bind="'+path+'" value="'+esc(val==null?"":val)+'" step="'+(step||"any")+'"'+(min==null?"":' min="'+min+'"')+'><span class="input-suffix">'+esc(suffix||"")+"</span></div></div>";}
  function inputField(label,path,val,placeholder,extra){return '<div class="field '+(extra||"")+'"><label>'+esc(label)+'</label><input class="input" type="text" data-bind="'+path+'" value="'+esc(val||"")+'" placeholder="'+esc(placeholder||"")+'"></div>';}
  function selectField(label,path,val,opts){return '<div class="field"><label>'+esc(label)+'</label><select class="select" data-bind="'+path+'">'+opts.map(function(o){var v=Array.isArray(o)?o[0]:o,l=Array.isArray(o)?o[1]:o;return '<option value="'+esc(v)+'"'+(String(v)===String(val)?" selected":"")+'>'+esc(l)+"</option>";}).join("")+"</select></div>";}
  function options(selected,opts){return opts.map(function(o){return '<option value="'+esc(o[0])+'"'+(String(o[0])===String(selected)?" selected":"")+'>'+esc(o[1])+"</option>";}).join("");}
  function header(eyebrow,title,sub,right){return '<div class="page-head"><div><p class="eyebrow">'+esc(eyebrow)+'</p><h1>'+esc(title)+'</h1><p class="page-subtitle">'+esc(sub||"")+"</p></div>"+(right||"")+"</div>";}
  function cardHead(title,sub,right){return '<div class="card-head"><div><h2>'+esc(title)+"</h2>"+(sub?'<p>'+esc(sub)+"</p>":"")+"</div>"+(right||"")+"</div>";}
  function stat(label,val,foot,icon,tone){return '<div class="card stat-card"><span class="stat-icon '+(tone||"")+'">'+icon+'</span><div class="stat-label">'+esc(label)+'</div><div class="stat-value">'+esc(val)+'</div><div class="stat-foot">'+esc(foot)+"</div></div>";}
  function go(page){S.activePage=pageNames[page]?page:"dashboard";save();document.querySelectorAll(".nav-item").forEach(function(b){b.classList.toggle("active",b.dataset.page===S.activePage);});text("page-crumb",pageNames[S.activePage]);render();window.scrollTo({top:0,behavior:"smooth"});}
  function render(){var root=el("app-view");if(!root)return;var p=S.activePage||"dashboard";root.innerHTML=p==="calculator"?calculator():p==="catalog"?catalog():p==="invoices"?invoices():p==="sales"?salesPage():p==="analytics"?analytics():p==="settings"?settingsPage():dashboard();}
  function liveSales(){var cancelled={};S.invoices.forEach(function(i){if(i.cancelled)cancelled[i.id]=1;});return S.sales.filter(function(s){return !s.invoiceId||!cancelled[s.invoiceId];});}
  function product(id){return S.products.find(function(p){return p.id===id;});}
  function byRef(ref){return S.products.find(function(p){return String(p.reference||"").toLowerCase()===String(ref||"").toLowerCase();});}
  function sold(id){return liveSales().filter(function(s){return s.productId===id;}).reduce(function(a,s){return a+n(s.quantity);},0);}
  function stock(p){return n(p.acquiredQty)-sold(p.id);}
  function rev(s){return n(s.revenue!=null?s.revenue:n(s.quantity)*n(s.unitPrice));}
  function cost(s){return n(s.costTotal!=null?s.costTotal:n(s.quantity)*n(s.costUnit));}
  function profit(s){return n(s.grossProfit!=null?s.grossProfit:rev(s)-cost(s));}
  function months(count){var now=new Date(),a=[];for(var i=count-1;i>=0;i--){var d=new Date(now.getFullYear(),now.getMonth()-i,1);a.push({key:d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0"),label:new Intl.DateTimeFormat("fr-FR",{month:"short"}).format(d).replace(".","")});}return a;}
  function chart(ms,vals){var max=Math.max.apply(null,vals.concat([1]));return '<div class="chart-wrap">'+ms.map(function(m,i){return '<div class="chart-col"><div class="chart-bar-zone"><span class="chart-tip">'+(vals[i]?fmt(vals[i]):"")+'</span><div class="chart-bar" style="height:'+Math.max(3,Math.round(vals[i]/max*145))+'px"></div></div><span class="chart-label">'+esc(m.label)+"</span></div>";}).join("")+"</div>";}
  function monthValues(ms,ss){return ms.map(function(m){return ss.filter(function(s){return String(s.date||"").slice(0,7)===m.key;}).reduce(function(a,s){return a+rev(s);},0);});}
  function dashboard(){
    var ss=liveSales(),m=today().slice(0,7),cur=ss.filter(function(s){return String(s.date||"").slice(0,7)===m;});
    var low=S.products.filter(function(p){return stock(p)<=n(S.settings.stockAlert);}),ms=months(6),vals=monthValues(ms,ss);
    var recent=ss.slice().sort(function(a,b){return String(b.date||"").localeCompare(String(a.date||""));}).slice(0,5);
    var recentRows=recent.map(function(s){return "<tr><td>"+dateFmt(s.date)+'</td><td><div class="product-name">'+esc(s.client||"Vente directe")+'</div><div class="product-ref">'+esc(s.invoiceNo||"Sans facture")+'</div></td><td>'+esc(s.name||"")+'</td><td class="num">'+money(rev(s))+"</td></tr>";}).join("");
    var lowRows=low.slice(0,5).map(function(p){var q=stock(p),c=q<=0?"out":"low";return '<tr><td><div class="product-name">'+esc(p.name)+'</div><div class="product-ref">'+esc(p.reference)+'</div></td><td class="num">'+fmt(q)+'</td><td><span class="stock-pill '+c+'">'+(q<=0?"Épuisé":"Stock bas")+"</span></td></tr>";}).join("");
    return header("KABAMAN · PILOTAGE","Bonjour, bienvenue.","Suivez vos coûts, votre stock et les ventes de votre activité.",'<button class="button button-primary" data-go="invoices">＋ &nbsp; Nouvelle facture</button>')+
    '<div class="grid stats-grid">'+stat("Chiffre d’affaires du mois",money(cur.reduce(function(a,s){return a+rev(s);},0)),"Ventes enregistrées ce mois","↗","teal")+stat("Bénéfice brut du mois",money(cur.reduce(function(a,s){return a+profit(s);},0)),"Chiffre d’affaires moins coût produit","◈","gold")+stat("Références au catalogue",fmt(S.products.length),"Produits suivis dans le stock","▦","blue")+stat("À réapprovisionner",fmt(low.length),"Seuil : "+fmt(S.settings.stockAlert)+" pièces","!","red")+"</div>"+
    '<div class="grid dashboard-grid"><section class="card card-pad">'+cardHead("Activité des ventes","Chiffre d’affaires des six derniers mois",'<span class="type-pill">DA</span>')+(ss.length?chart(ms,vals)+'<div class="legend"><span class="legend-dot"></span>Chiffre d’affaires enregistré</div>':'<div class="empty-state"><strong>Votre activité apparaîtra ici</strong>Enregistre une vente ou une facture pour commencer.</div>')+"</section>"+
    '<section class="card card-pad">'+cardHead("Raccourcis","Actions fréquentes")+'<div class="quick-grid">'+quick("＋","Calculer un coût","Préparer un prix de vente","calculator")+quick("▦","Ajouter un produit","Compléter le catalogue","catalog")+quick("▤","Créer une facture","Préparer une vente client","invoices")+quick("↗","Saisir une vente","Mettre le stock à jour","sales")+"</div></section></div>"+
    '<div class="grid lower-grid"><section class="card table-card">'+cardHead("Ventes récentes","Dernières lignes ajoutées",'<button class="button button-quiet button-small" data-go="sales">Tout voir →</button>')+(recentRows?'<div class="table-scroll"><table><thead><tr><th>Date</th><th>Client / facture</th><th>Produit</th><th class="num">Montant</th></tr></thead><tbody>'+recentRows+"</tbody></table></div>":'<div class="empty-state"><strong>Aucune vente enregistrée</strong>Les ventes et factures apparaîtront ici.</div>')+"</section>"+
    '<section class="card table-card">'+cardHead("État du stock","Produits à contrôler",'<button class="button button-quiet button-small" data-go="catalog">Catalogue →</button>')+(lowRows?'<div class="table-scroll"><table><thead><tr><th>Produit</th><th class="num">Restant</th><th>État</th></tr></thead><tbody>'+lowRows+"</tbody></table></div>":'<div class="empty-state"><strong>Tout est en ordre</strong>Aucun produit sous le seuil.</div>')+"</section></div>";
  }
  function quick(ic,t,d,p){return '<button class="quick-action" data-go="'+p+'"><span class="qa-icon">'+ic+'</span><strong>'+esc(t)+'</strong><small>'+esc(d)+"</small></button>";}

  function eff(v,setting){return v==null||v===""?n(setting):n(v);}
  function buyDA(v,currency){return n(v)*(currency==="EUR"?n(S.settings.eurToDzd):1);}
  function calcMulti(){
    var c=S.multi,rows=c.lines.map(function(l){var q=Math.max(0,n(l.quantity)),unit=buyDA(l.buyPrice,l.currency);return {src:l,q:q,buy:unit*q,unitBuy:unit};});
    var purchases=rows.reduce(function(a,x){return a+x.buy;},0),travel=n(c.flight)+n(c.visa)+n(c.hotel)+n(c.transport);
    var cas=n(S.settings.casnosMonthly)*n(c.casnosShare)/100;
    var tax=(c.activity==="Oui"?n(c.monthlyRevenue)*n(S.settings.taxActivityRate)/100:n(S.settings.taxFixedMonthly))*n(c.taxShare)/100;
    var customs=purchases*eff(c.customsRate,S.settings.customsRate)/100,bank=purchases*eff(c.bankRate,S.settings.bankRate)/100;
    var overhead=travel+cas+tax+customs+bank;
    rows.forEach(function(x){x.share=purchases?x.buy/purchases:0;x.alloc=overhead*x.share;x.total=x.buy+x.alloc;x.unitCost=x.q?x.total/x.q:0;x.wholesale=x.unitCost*(1+eff(c.wholesaleMarkup,S.settings.wholesaleMarkup)/100);x.retail=x.unitCost*(1+eff(c.retailMarkup,S.settings.retailMarkup)/100);});
    return {rows:rows,purchases:purchases,travel:travel,cas:cas,tax:tax,customs:customs,bank:bank,overhead:overhead,total:purchases+overhead,wm:eff(c.wholesaleMarkup,S.settings.wholesaleMarkup),rm:eff(c.retailMarkup,S.settings.retailMarkup)};
  }
  function calcSingle(){
    var c=S.single,q=Math.max(0,n(c.quantity)),unitBuy=buyDA(c.buyPrice,c.currency),purchases=q*unitBuy,travel=n(c.flight)+n(c.visa)+n(c.hotel)+n(c.transport);
    var cas=n(S.settings.casnosMonthly)*n(c.casnosShare)/100;
    var tax=(c.activity==="Oui"?n(c.monthlyRevenue)*n(S.settings.taxActivityRate)/100:n(S.settings.taxFixedMonthly))*n(c.taxShare)/100;
    var customsBase=c.customsBase==null||c.customsBase===""?purchases:n(c.customsBase),bankBase=c.bankBase==null||c.bankBase===""?purchases:n(c.bankBase);
    var customs=customsBase*eff(c.customsRate,S.settings.customsRate)/100,bank=bankBase*eff(c.bankRate,S.settings.bankRate)/100;
    var total=purchases+travel+cas+tax+customs+bank,unitCost=q?total/q:0;
    return {q:q,unitBuy:unitBuy,purchases:purchases,travel:travel,cas:cas,tax:tax,customs:customs,bank:bank,total:total,unitCost:unitCost,wholesale:unitCost*(1+eff(c.wholesaleMarkup,S.settings.wholesaleMarkup)/100),retail:unitCost*(1+eff(c.retailMarkup,S.settings.retailMarkup)/100)};
  }
  function calcLine(label,value,total){return '<div class="summary-line'+(total?" total":"")+'"><span>'+esc(label)+'</span><strong>'+esc(value)+"</strong></div>";}
  function calcResults(){
    if(S.calcMode==="single"){
      var r=calcSingle();
      return '<section class="price-feature"><small>COÛT TOTAL DE L’IMPORT</small><strong>'+money(r.total)+'</strong><span>Pour '+fmt(r.q)+' pièce(s)</span></section>'+
        '<section class="card card-pad">'+cardHead("Détail du calcul","Charges imputées à cet import")+
        '<div class="calc-summary">'+calcLine("Total achats",money(r.purchases))+calcLine("Frais de voyage",money(r.travel))+calcLine("CASNOS imputé",money(r.cas))+calcLine("Impôt imputé",money(r.tax))+calcLine("Douanes",money(r.customs))+calcLine("Frais bancaires",money(r.bank))+calcLine("Coût réel / pièce",money(r.unitCost),true)+'</div></section>'+
        '<section class="card card-pad">'+cardHead("Prix proposés","Majoration appliquée au coût réel")+
        '<div class="price-pair"><div class="price-mini"><small>Gros</small><strong>'+money(r.wholesale)+'</strong></div><div class="price-mini"><small>Détail</small><strong>'+money(r.retail)+'</strong></div></div></section>';
    }
    var r0=calcMulti(),valid=r0.rows.filter(function(x){return x.q;});
    var avgW=valid.reduce(function(a,x){return a+x.wholesale*x.q;},0)/(valid.reduce(function(a,x){return a+x.q;},0)||1);
    var avgR=valid.reduce(function(a,x){return a+x.retail*x.q;},0)/(valid.reduce(function(a,x){return a+x.q;},0)||1);
    return '<section class="card card-pad">'+cardHead("Résumé de l’import",valid.length+" produit(s) avec quantité")+
      '<div class="calc-summary">'+calcLine("Total achats",money(r0.purchases))+calcLine("Frais de voyage",money(r0.travel))+calcLine("CASNOS imputé",money(r0.cas))+calcLine("Impôt imputé",money(r0.tax))+calcLine("Douanes estimées",money(r0.customs))+calcLine("Frais bancaires",money(r0.bank))+calcLine("Frais à répartir",money(r0.overhead),true)+calcLine("Coût total de l’import",money(r0.total),true)+'</div><p class="price-note">Les frais sont répartis au prorata de la valeur d’achat de chaque produit.</p></section>'+
      '<section class="price-feature"><small>COÛT TOTAL DE L’IMPORT</small><strong>'+money(r0.total)+'</strong><span>Achats et frais réunis</span></section>'+
      '<section class="card card-pad">'+cardHead("Prix de vente moyens","Majoration du coût unitaire")+
      '<div class="price-pair"><div class="price-mini"><small>Gros · +'+fmt(r0.wm,1)+'%</small><strong>'+money(avgW)+'</strong></div><div class="price-mini"><small>Détail · +'+fmt(r0.rm,1)+'%</small><strong>'+money(avgR)+'</strong></div></div></section>';
  }
  function calculator(){
    var mode='<div class="mode-switch"><button data-calc-mode="multi" class="'+(S.calcMode==="multi"?"active":"")+'">Import multi-produits</button><button data-calc-mode="single" class="'+(S.calcMode==="single"?"active":"")+'">Produit unique</button></div>';
    return header("PRÉPARATION D’IMPORTATION","Calcul des coûts","Répartis les frais d’import et calcule le coût réel et les prix de vente.",mode)+(S.calcMode==="multi"?multiForm():singleForm());
  }
  function multiForm(){
    var c=S.multi,rows=calcMulti().rows;
    var table=rows.map(function(x,i){return '<tr><td class="muted">'+(i+1)+'</td><td><input class="input ref-input" data-multi="'+i+'|reference" value="'+esc(x.src.reference)+'" placeholder="Référence"></td><td><input class="input name-input" data-multi="'+i+'|name" value="'+esc(x.src.name)+'" placeholder="Nom du produit"></td><td><input class="input" type="number" min="0" data-multi="'+i+'|quantity" value="'+esc(x.src.quantity)+'" placeholder="0"></td><td><div class="flex-between" style="gap:4px"><input class="input" type="number" min="0" data-multi="'+i+'|buyPrice" value="'+esc(x.src.buyPrice)+'" placeholder="0"><select class="select" style="width:62px" data-multi="'+i+'|currency"><option value="DA"'+(x.src.currency!=="EUR"?" selected":"")+'>DA</option><option value="EUR"'+(x.src.currency==="EUR"?" selected":"")+'>€</option></select></div></td><td class="num" data-r="'+i+'|buy">'+money(x.buy)+'</td><td class="num" data-r="'+i+'|alloc">'+money(x.alloc)+'</td><td class="num strong" data-r="'+i+'|unit">'+money(x.unitCost)+'</td><td class="num" data-r="'+i+'|wholesale">'+money(x.wholesale)+'</td><td class="num" data-r="'+i+'|retail">'+money(x.retail)+'</td><td><button class="button button-icon" data-remove-calc="'+i+'">×</button></td></tr>';}).join("");
    var general='<div class="form-grid four">'+moneyField("Billet d’avion","multi.flight",c.flight,"DA","100",0)+moneyField("Visa","multi.visa",c.visa,"DA","100",0)+moneyField("Hôtel","multi.hotel",c.hotel,"DA","100",0)+moneyField("Transport & nourriture","multi.transport",c.transport,"DA","100",0)+moneyField("Part CASNOS imputée","multi.casnosShare",c.casnosShare,"%","1",0)+selectField("Activité ce mois-ci ?","multi.activity",c.activity,["Non","Oui"])+moneyField("Chiffre d’affaires mensuel","multi.monthlyRevenue",c.monthlyRevenue,"DA","100",0)+moneyField("Part impôt imputée","multi.taxShare",c.taxShare,"%","1",0)+moneyField("Taux douanier","multi.customsRate",eff(c.customsRate,S.settings.customsRate),"%","0.1",0)+moneyField("Taux bancaire","multi.bankRate",eff(c.bankRate,S.settings.bankRate),"%","0.1",0)+moneyField("Majoration de gros","multi.wholesaleMarkup",eff(c.wholesaleMarkup,S.settings.wholesaleMarkup),"%","1",0)+moneyField("Majoration de détail","multi.retailMarkup",eff(c.retailMarkup,S.settings.retailMarkup),"%","1",0)+"</div>";
    return '<div class="calc-layout"><div class="calc-main"><section class="card card-pad"><div class="section-block"><div class="section-title"><span class="section-number">1</span><h3>Frais, charges et taux</h3></div>'+general+'</div><p class="price-note">Les valeurs par défaut viennent des paramètres et restent modifiables pour cet import.</p></section><section class="card table-card"><div class="card-pad">'+cardHead("Produits de l’import","Frais communs répartis au prorata de la valeur d’achat.",'<span class="type-pill">'+c.lines.length+" ligne(s)</span>")+'</div><div class="table-scroll"><table class="calc-table"><thead><tr><th>#</th><th>Référence</th><th>Produit</th><th>Qté</th><th>Prix achat / pièce</th><th class="num">Achats</th><th class="num">Frais attribués</th><th class="num">Coût réel / pièce</th><th class="num">Gros</th><th class="num">Détail</th><th></th></tr></thead><tbody>'+table+'</tbody></table></div><div class="line-add-row"><span>Conversion EUR → DA : '+fmt(S.settings.eurToDzd)+' DA / EUR.</span><div class="inline-actions"><button class="button button-outline button-small" data-action="add-calc">＋ Ajouter une ligne</button><button class="button button-primary button-small" data-action="save-multi">Ajouter au catalogue</button></div></div></section><div class="notice warning">Les taux de douane, d’impôt et les charges sont des hypothèses à vérifier pour chaque opération.</div></div><aside class="calc-side" id="calc-results">'+calcResults()+"</aside></div>";
  }
  function singleForm(){
    var c=S.single,r=calcSingle();
    return '<div class="calc-layout"><div class="calc-main"><section class="card card-pad"><div class="section-block"><div class="section-title"><span class="section-number">1</span><h3>Produit et prix d’achat</h3></div><div class="form-grid four">'+inputField("Référence","single.reference",c.reference,"Ex. PH3310")+inputField("Nom du produit","single.name",c.name,"Désignation")+moneyField("Quantité","single.quantity",c.quantity,"pièces","1",0)+'<div class="field"><label>Prix d’achat / pièce</label><div class="flex-between" style="gap:4px"><input class="input" type="number" min="0" data-bind="single.buyPrice" value="'+esc(c.buyPrice)+'"><select class="select" style="width:64px" data-bind="single.currency"><option value="DA"'+(c.currency!=="EUR"?" selected":"")+'>DA</option><option value="EUR"'+(c.currency==="EUR"?" selected":"")+'>€</option></select></div></div></div></div><div class="section-block"><div class="section-title"><span class="section-number">2</span><h3>Frais, charges et taux</h3></div><div class="form-grid four">'+moneyField("Billet d’avion","single.flight",c.flight,"DA","100",0)+moneyField("Visa","single.visa",c.visa,"DA","100",0)+moneyField("Hôtel","single.hotel",c.hotel,"DA","100",0)+moneyField("Transport & nourriture","single.transport",c.transport,"DA","100",0)+moneyField("Part CASNOS imputée","single.casnosShare",c.casnosShare,"%","1",0)+selectField("Activité ce mois-ci ?","single.activity",c.activity,["Non","Oui"])+moneyField("Chiffre d’affaires mensuel","single.monthlyRevenue",c.monthlyRevenue,"DA","100",0)+moneyField("Part impôt imputée","single.taxShare",c.taxShare,"%","1",0)+moneyField("Base douanière","single.customsBase",c.customsBase==null?r.purchases:c.customsBase,"DA","100",0)+moneyField("Taux douanier","single.customsRate",eff(c.customsRate,S.settings.customsRate),"%","0.1",0)+moneyField("Base bancaire","single.bankBase",c.bankBase==null?r.purchases:c.bankBase,"DA","100",0)+moneyField("Taux bancaire","single.bankRate",eff(c.bankRate,S.settings.bankRate),"%","0.1",0)+moneyField("Majoration de gros","single.wholesaleMarkup",eff(c.wholesaleMarkup,S.settings.wholesaleMarkup),"%","1",0)+moneyField("Majoration de détail","single.retailMarkup",eff(c.retailMarkup,S.settings.retailMarkup),"%","1",0)+'</div></div><div class="line-add-row"><span>Les bases de douane et banque suivent le total des achats jusqu’à modification.</span><button class="button button-primary button-small" data-action="save-single">Ajouter au catalogue</button></div></section><div class="notice warning">Vérifie les taux préremplis avant chaque import.</div></div><aside class="calc-side" id="calc-results">'+calcResults()+"</aside></div>";
  }
  function updateCalc(){
    if(S.calcMode==="multi"){var r=calcMulti();r.rows.forEach(function(x,i){["buy","alloc","unit","wholesale","retail"].forEach(function(k){var el0=document.querySelector('[data-r="'+i+"|"+k+'"]');if(el0)el0.textContent=money(k==="buy"?x.buy:k==="alloc"?x.alloc:k==="unit"?x.unitCost:x[k]);});});}
    var target=el("calc-results");if(target)target.innerHTML=calcResults();save();
  }
  function addProducts(list){
    var count=0;
    list.forEach(function(x){if(!x.q||!x.unitCost||(!x.name&&!x.reference))return;
      var ref=String(x.reference||("KAB-"+String(Date.now()).slice(-6)+"-"+(count+1))).trim(),p=byRef(ref);
      if(p){var rem=Math.max(0,stock(p)),total=rem+x.q;p.unitCost=total?(rem*n(p.unitCost)+x.q*x.unitCost)/total:x.unitCost;p.acquiredQty=n(p.acquiredQty)+x.q;p.name=x.name||p.name;p.wholesalePrice=x.wholesale;p.retailPrice=x.retail;p.negotiatedPrice=x.retail;}
      else S.products.push({id:uid(),reference:ref,name:x.name||ref,category:"",supplier:"",acquiredQty:x.q,unitCost:x.unitCost,wholesalePrice:x.wholesale,retailPrice:x.retail,negotiatedPrice:x.retail});
      count++;
    });
    if(!count){toast("Indique un nom, une quantité et un prix d’achat.",true);return;}save();toast(count+" produit(s) ajouté(s).");go("catalog");
  }
  function saveMulti(){addProducts(calcMulti().rows.map(function(x){return {reference:x.src.reference,name:x.src.name,q:x.q,unitCost:x.unitCost,wholesale:x.wholesale,retail:x.retail};}));}
  function saveSingle(){var c=S.single,r=calcSingle();addProducts([{reference:c.reference,name:c.name,q:r.q,unitCost:r.unitCost,wholesale:r.wholesale,retail:r.retail}]);}

  function catalog(){
    var ps=S.products.slice().sort(function(a,b){return String(a.name).localeCompare(String(b.name),"fr");}),q=(S.catalogSearch||"").toLowerCase();
    if(q)ps=ps.filter(function(p){return [p.reference,p.name,p.category,p.supplier].join(" ").toLowerCase().indexOf(q)>=0;});
    var rows=ps.map(function(p){var st=stock(p),cl=st<=0?"out":st<=n(S.settings.stockAlert)?"low":"ok";return '<tr><td><div class="product-name">'+esc(p.name)+'</div><div class="product-ref">'+esc(p.reference)+'</div></td><td>'+esc(p.category||"—")+'</td><td class="num">'+fmt(p.acquiredQty)+'</td><td class="num">'+fmt(sold(p.id))+'</td><td class="num"><span class="stock-pill '+cl+'">'+fmt(st)+'</span></td><td class="num">'+money(p.unitCost)+'</td><td class="num">'+money(p.wholesalePrice)+'</td><td class="num">'+money(p.retailPrice)+'</td><td><div class="inline-actions"><button class="button button-outline button-small" data-edit="'+p.id+'">Modifier</button><button class="button button-icon" data-delete="'+p.id+'">×</button></div></td></tr>';}).join("");
    var total=S.products.reduce(function(a,p){return a+Math.max(0,stock(p));},0),low=S.products.filter(function(p){return stock(p)<=n(S.settings.stockAlert);}).length,value=S.products.reduce(function(a,p){return a+Math.max(0,stock(p))*n(p.unitCost);},0);
    return header("CATALOGUE","Produits & stock","Gère les références, les prix de vente et les quantités disponibles.",'<div class="toolbar"><button class="button button-outline" data-action="export-catalog">⇩ Exporter CSV</button><button class="button button-outline" data-action="import-csv">⇧ Importer CSV</button><button class="button button-primary" data-action="new-product">＋ Nouveau produit</button><input id="csv-file" type="file" accept=".csv,text/csv" hidden></div>')+
    '<div class="grid stats-grid">'+stat("Références",fmt(S.products.length),"Produits au catalogue","▦","blue")+stat("Pièces en stock",fmt(total),"Quantités restantes positives","◫","teal")+stat("Stock à contrôler",fmt(low),"Seuil : "+fmt(S.settings.stockAlert)+" pièces","!","gold")+stat("Valeur du stock",money(value),"Au coût réel unitaire","◈","red")+"</div>"+
    '<section class="card table-card"><div class="card-pad flex-between"><div><h2>Catalogue des produits</h2><p class="page-subtitle">Les ventes diminuent automatiquement les quantités disponibles.</p></div><div class="search-box"><span>⌕</span><input class="input" id="catalog-search" type="search" value="'+esc(S.catalogSearch||"")+'" placeholder="Rechercher un produit"></div></div>'+(rows?'<div class="table-scroll"><table><thead><tr><th>Produit / référence</th><th>Catégorie</th><th class="num">Acheté</th><th class="num">Vendu</th><th class="num">Stock restant</th><th class="num">Coût réel</th><th class="num">Prix gros</th><th class="num">Prix détail</th><th>Actions</th></tr></thead><tbody>'+rows+"</tbody></table></div>":'<div class="empty-state"><strong>'+(S.products.length?"Aucun produit trouvé":"Le catalogue est vide")+"</strong>"+(S.products.length?"Modifie la recherche.":"Ajoute un produit ou importe un CSV.")+"</div>")+"</section>";
  }
  function modal(title,body,actions){
    el("modal-root").innerHTML='<div class="modal-backdrop" data-backdrop><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>'+esc(title)+'</h2><button class="modal-close" data-action="close-modal">×</button></div><div class="modal-body">'+body+'</div><div class="modal-foot">'+actions+"</div></div></div>";
  }
  function productModal(id){
    var p=id?product(id):null;if(p)p=Object.assign({},p);
    var body='<input type="hidden" id="p-id" value="'+(p?esc(p.id):"")+'"><div class="form-grid two">'+inputField("Référence unique *","modal.ref",p?p.reference:"","Ex. PH3310")+inputField("Désignation *","modal.name",p?p.name:"","Nom du produit")+inputField("Catégorie","modal.category",p?p.category:"","Ex. Accessoires")+inputField("Fournisseur / origine","modal.supplier",p?p.supplier:"","Origine")+moneyField("Quantité achetée","modal.qty",p?p.acquiredQty:0,"pièces","1",0)+moneyField("Coût réel unitaire","modal.cost",p?p.unitCost:0,"DA","1",0)+moneyField("Prix de gros","modal.wholesale",p?p.wholesalePrice:0,"DA","1",0)+moneyField("Prix de détail","modal.retail",p?p.retailPrice:0,"DA","1",0)+moneyField("Prix négocié indicatif","modal.negotiated",p?p.negotiatedPrice:0,"DA","1",0)+"</div><p class=\"price-note\">Le stock restant est calculé : quantités achetées moins les ventes.</p>";
    modal(p?"Modifier le produit":"Nouveau produit",body,'<button class="button button-outline" data-action="close-modal">Annuler</button><button class="button button-primary" data-action="save-product">Enregistrer</button>');
    S.modalProduct=p;
  }
  function saveProduct(){
    function val(name){var e=document.querySelector('[data-bind="modal.'+name+'"]');return e?e.value:"";}
    var id=el("p-id").value,ref=val("ref").trim(),name=val("name").trim(),dup=byRef(ref);
    if(!ref||!name){toast("Référence et désignation obligatoires.",true);return;}if(dup&&dup.id!==id){toast("Cette référence existe déjà.",true);return;}
    var p={id:id||uid(),reference:ref,name:name,category:val("category"),supplier:val("supplier"),acquiredQty:n(val("qty")),unitCost:n(val("cost")),wholesalePrice:n(val("wholesale")),retailPrice:n(val("retail")),negotiatedPrice:n(val("negotiated"))};
    if(id){var ix=S.products.findIndex(function(x){return x.id===id;});if(ix>=0)S.products[ix]=Object.assign({},S.products[ix],p);}else S.products.push(p);
    delete S.modalProduct;save();el("modal-root").innerHTML="";render();toast("Produit enregistré.");
  }
  function removeProduct(id){var p=product(id);if(!p)return;if(S.sales.some(function(s){return s.productId===id;})){toast("Ce produit a un historique de ventes. Garde-le pour préserver les rapports.",true);return;}if(!confirm("Supprimer "+p.name+" du catalogue ?"))return;S.products=S.products.filter(function(x){return x.id!==id;});save();render();toast("Produit supprimé.");}
  function csvVal(v){return '"'+String(v==null?"":v).replace(/"/g,'""')+'"';}
  function download(name,content,type){var blob=new Blob([content],{type:type||"application/octet-stream"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url);},1000);}
  function exportCatalog(){var lines=[["reference","designation","categorie","fournisseur","quantite_achetee","quantite_vendue","stock_restant","cout_unitaire_DA","prix_gros_DA","prix_detail_DA","prix_negocie_DA"].join(";")];S.products.forEach(function(p){lines.push([p.reference,p.name,p.category,p.supplier,p.acquiredQty,sold(p.id),stock(p),p.unitCost,p.wholesalePrice,p.retailPrice,p.negotiatedPrice].map(csvVal).join(";"));});download("kabaman_catalogue_"+today()+".csv","\ufeff"+lines.join("\r\n"),"text/csv;charset=utf-8");}
  function parseCSV(s){var delim=(s.split(/\r?\n/)[0].match(/;/g)||[]).length>(s.split(/\r?\n/)[0].match(/,/g)||[]).length?";":",",rows=[],row=[],v="",quoted=false;for(var i=0;i<s.length;i++){var c=s[i];if(quoted){if(c==='"'&&s[i+1]==='"'){v+='"';i++;}else if(c==='"')quoted=false;else v+=c;}else if(c==='"')quoted=true;else if(c===delim){row.push(v);v="";}else if(c==="\n"){row.push(v.replace(/\r$/,""));rows.push(row);row=[];v="";}else v+=c;}if(v||row.length){row.push(v);rows.push(row);}return rows.filter(function(r){return r.some(function(x){return String(x).trim();});});}
  function importCSV(file){if(!file)return;var rd=new FileReader();rd.onload=function(){try{var rows=parseCSV(String(rd.result||"").replace(/^\ufeff/,""));if(rows.length<2)throw Error("Aucune ligne de produit trouvée.");var hs=rows[0].map(function(x){return x.toLowerCase().trim().replace(/\s+/g,"_");});function ix(list){return hs.findIndex(function(x){return list.indexOf(x)>=0;});}var c={r:ix(["reference","référence","ref"]),n:ix(["designation","désignation","nom"]),cat:ix(["categorie","catégorie"]),sup:ix(["fournisseur","origine"]),q:ix(["quantite_achetee","quantité_achetée","quantite","quantité"]),cost:ix(["cout_unitaire_da","coût_unitaire_da","cout_unitaire"]),w:ix(["prix_gros_da","prix_gros"]),ret:ix(["prix_detail_da","prix_detail"]),neg:ix(["prix_negocie_da","prix_negocie"])};if(c.r<0||c.n<0)throw Error("Colonnes requises : reference et designation.");var count=0;rows.slice(1).forEach(function(r){var ref=(r[c.r]||"").trim(),name=(r[c.n]||"").trim();if(!ref||!name)return;var old=byRef(ref),p={id:old?old.id:uid(),reference:ref,name:name,category:c.cat<0?(old?old.category:""):r[c.cat],supplier:c.sup<0?(old?old.supplier:""):r[c.sup],acquiredQty:c.q<0?(old?old.acquiredQty:0):n(r[c.q]),unitCost:c.cost<0?(old?old.unitCost:0):n(r[c.cost]),wholesalePrice:c.w<0?(old?old.wholesalePrice:0):n(r[c.w]),retailPrice:c.ret<0?(old?old.retailPrice:0):n(r[c.ret]),negotiatedPrice:c.neg<0?(old?old.negotiatedPrice:0):n(r[c.neg])};if(old)S.products[S.products.indexOf(old)]=p;else S.products.push(p);count++;});save();render();toast(count+" produit(s) importé(s).");}catch(e){toast(e.message||"CSV illisible.",true);}};rd.readAsText(file,"utf-8");}

  function invoiceNumber(date){var prefix="KAB-"+String(date||today()).slice(2,4)+"-",max=0;S.invoices.forEach(function(i){if(String(i.number||"").indexOf(prefix)===0)max=Math.max(max,parseInt(i.number.slice(prefix.length),10)||0);});return prefix+String(max+1).padStart(4,"0");}
  function ensureDraft(){if(!S.draft)S.draft={id:uid(),number:invoiceNumber(today()),date:today(),due:"",client:"",phone:"",address:"",market:"",type:"Gros",paymentMethod:"Espèces",paymentStatus:"Impayé",amountPaid:0,discount:0,lines:[{productId:"",quantity:1,customPrice:"",unit:"pièce"}]};if(!Array.isArray(S.draft.lines)||!S.draft.lines.length)S.draft.lines=[{productId:"",quantity:1,customPrice:"",unit:"pièce"}];}
  function linePrice(line,type){var p=product(line.productId);if(!p)return 0;if(type==="Gros")return n(p.wholesalePrice);if(type==="Détail")return n(p.retailPrice);return n(line.customPrice!==""&&line.customPrice!=null?line.customPrice:p.negotiatedPrice);}
  function totals(d){var sub=d.lines.reduce(function(a,l){return a+Math.max(0,n(l.quantity))*linePrice(l,d.type);},0),disc=Math.min(sub,Math.max(0,n(d.discount)));return {sub:sub,disc:disc,net:sub-disc};}
  function miniInvoice(d,t){return '<div class="invoice-brand-row"><div><strong>'+esc(S.settings.companyName)+'</strong><div class="product-ref">'+esc(S.settings.activity)+'</div></div><span>FACTURE<br>'+esc(d.number)+'</span></div><h3>Informations client</h3><div class="mini-meta"><span>Client</span><strong>'+esc(d.client||"—")+'</strong><span>Date</span><strong>'+dateFmt(d.date)+'</strong><span>Type</span><strong>'+esc(d.type)+'</strong><span>Échéance</span><strong>'+dateFmt(d.due)+'</strong></div><div class="mini-total"><span>NET À PAYER</span><strong>'+money(t.net)+'</strong></div><div class="arabic" style="margin-top:10px;color:#8492a0">فاتورة · المجموع الواجب دفعه</div>';}
  function invoicePreview(){
    ensureDraft();var d=S.draft,t=totals(d),products='<option value="">Choisir un produit…</option>'+S.products.map(function(p){return '<option value="'+p.id+'">'+esc(p.reference+" · "+p.name+" · stock "+fmt(stock(p)))+"</option>";}).join("");
    var rows=d.lines.map(function(l,i){var p=product(l.productId),price=linePrice(l,d.type);var priceInput=d.type==="Négocié"?'<input class="input" type="number" min="0" data-invline="'+i+'|customPrice" value="'+esc(l.customPrice||(p?p.negotiatedPrice:""))+'">':'<input class="input" readonly value="'+esc(price)+'">';return '<tr><td><select class="select item-select" data-invline="'+i+'|productId">'+products.replace('value="'+esc(l.productId)+'"','value="'+esc(l.productId)+'" selected')+'</select>'+(p?'<div class="product-ref">Stock : '+fmt(stock(p))+" pièce(s)</div>":"")+'</td><td><input class="input" type="number" min="0" data-invline="'+i+'|quantity" value="'+esc(l.quantity)+'"></td><td>'+priceInput+'</td><td><input class="input" data-invline="'+i+'|unit" value="'+esc(l.unit||"pièce")+'"></td><td class="num strong">'+money(n(l.quantity)*price)+'</td><td><button class="button button-icon" data-rm-inv="'+i+'">×</button></td></tr>';}).join("");
    var hist=S.invoices.slice().sort(function(a,b){return String(b.date).localeCompare(String(a.date));}).map(function(i){return '<tr><td><button class="button button-quiet button-small" data-open-inv="'+i.id+'">'+esc(i.number)+'</button></td><td>'+dateFmt(i.date)+'</td><td>'+esc(i.client||"Client comptant")+'</td><td>'+(i.cancelled?'<span class="status-pill cancelled">Annulée</span>':'<span class="status-pill '+statusClass(i.paymentStatus)+'">'+esc(i.paymentStatus)+'</span>')+'</td><td class="num">'+money(i.net)+'</td><td><div class="inline-actions"><button class="button button-outline button-small" data-open-inv="'+i.id+'">Ouvrir</button>'+(i.cancelled?"":'<button class="button button-icon" data-cancel-inv="'+i.id+'">×</button>')+"</div></td></tr>";}).join("");
    return header("VENTES CLIENTS","Factures","Prépare, valide et imprime une facture bilingue.",'<span class="type-pill">'+S.invoices.length+" facture(s)</span>")+
    '<div class="invoice-layout"><div class="calc-main"><section class="card card-pad">'+cardHead("Nouvelle facture","Le stock est actualisé après validation.",'<button class="button button-light button-small" data-action="new-invoice">Nouvelle</button>')+
    '<div class="form-grid four">'+inputField("N° facture","draft.number",d.number,"KAB-YY-0001")+'<div class="field"><label>Date</label><input type="date" class="input" data-draft="date" value="'+esc(d.date)+'"></div><div class="field"><label>Échéance</label><input type="date" class="input" data-draft="due" value="'+esc(d.due)+'"></div>'+selectField("Type de prix","draft.type",d.type,["Gros","Détail","Négocié"])+inputField("Client","draft.client",d.client,"Nom du client")+inputField("Téléphone","draft.phone",d.phone,"Téléphone")+inputField("Adresse","draft.address",d.address,"Adresse de livraison")+inputField("Marché","draft.market",d.market,"Marché / ville")+selectField("Mode de paiement","draft.paymentMethod",d.paymentMethod,["Espèces","Virement","Autre"])+selectField("État du paiement","draft.paymentStatus",d.paymentStatus,["Payé","Partiellement payé","Impayé"])+moneyField("Montant déjà reçu","draft.amountPaid",d.amountPaid,"DA","100",0)+moneyField("Remise","draft.discount",d.discount,"DA","100",0)+'</div><div class="divider"></div><div class="section-title"><span class="section-number">1</span><h3>Articles facturés</h3></div>'+
    (S.products.length?'<div class="table-scroll"><table class="invoice-lines"><thead><tr><th>Produit</th><th>Qté</th><th>Prix unitaire</th><th>Unité</th><th class="num">Total</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="line-add-row"><span>Prix liés au catalogue selon le type choisi.</span><button class="button button-outline button-small" data-action="add-inv-line">＋ Ajouter une ligne</button></div>':'<div class="notice warning">Ajoute d’abord les produits et leurs prix au catalogue.</div>')+
    '<div class="flex-between" style="padding-top:12px"><span class="muted tiny">Valider enregistre la facture et ses ventes.</span><button class="button button-primary" data-action="save-invoice">Valider la facture →</button></div></section><section class="card table-card">'+cardHead("Factures enregistrées","Les factures annulées sont exclues des analyses.")+(hist?'<div class="table-scroll"><table><thead><tr><th>N° facture</th><th>Date</th><th>Client</th><th>État</th><th class="num">Net à payer</th><th>Actions</th></tr></thead><tbody>'+hist+"</tbody></table></div>":'<div class="empty-state"><strong>Aucune facture</strong>Les factures validées apparaîtront ici.</div>')+"</section></div>"+
    '<aside class="invoice-aside"><section class="card card-pad">'+cardHead("Récapitulatif","Montants de la facture en préparation")+'<div class="calc-summary">'+calcLine("Sous-total",money(t.sub))+calcLine("Remise","− "+money(t.disc))+calcLine("Net à payer",money(t.net),true)+calcLine("Déjà reçu",money(Math.min(t.net,n(d.amountPaid))))+calcLine("Reste à payer",money(Math.max(0,t.net-n(d.amountPaid))))+'</div><p class="price-note">La majoration est ajoutée au coût réel ; elle ne représente pas une marge nette du prix de vente.</p></section><section class="invoice-preview-mini" id="mini-preview">'+miniInvoice(d,t)+'</section><button class="button button-dark w-full" data-action="print-draft">⎙ &nbsp; Aperçu & imprimer</button></aside></div>';
  }
  function updateDraft(){var d=S.draft,t=totals(d),p=el("mini-preview");if(p)p.innerHTML=miniInvoice(d,t);var vals=document.querySelectorAll(".invoice-aside .summary-line strong");if(vals.length>=5){vals[0].textContent=money(t.sub);vals[1].textContent="− "+money(t.disc);vals[2].textContent=money(t.net);vals[3].textContent=money(Math.min(t.net,n(d.amountPaid)));vals[4].textContent=money(Math.max(0,t.net-n(d.amountPaid)));}document.querySelectorAll(".invoice-lines tbody tr").forEach(function(tr,i){var c=tr.querySelector(".strong");if(c&&d.lines[i])c.textContent=money(n(d.lines[i].quantity)*linePrice(d.lines[i],d.type));});save();}
  function statusClass(s){return s==="Payé"?"paid":s==="Partiellement payé"?"partial":"unpaid";}
  function invoices(){return invoicePreview();}
  function saveInvoice(){
    var d=S.draft,t=totals(d),lines=d.lines.map(function(l){return {l:l,p:product(l.productId),q:n(l.quantity),price:linePrice(l,d.type)};}).filter(function(x){return x.p&&x.q>0;});
    if(!String(d.number||"").trim()){toast("Le numéro de facture est obligatoire.",true);return;}if(!lines.length){toast("Ajoute au moins un article.",true);return;}if(S.invoices.some(function(i){return i.number===d.number&&!i.cancelled;})){toast("Ce numéro existe déjà.",true);return;}
    if(d.paymentStatus==="Payé")d.amountPaid=t.net;if(d.paymentStatus==="Impayé")d.amountPaid=0;d.amountPaid=Math.min(t.net,Math.max(0,n(d.amountPaid)));
    if(d.paymentStatus==="Partiellement payé"&&d.amountPaid>=t.net&&t.net>0)d.paymentStatus="Payé";
    var inv={id:d.id||uid(),number:d.number,date:d.date||today(),due:d.due||"",client:d.client||"",phone:d.phone||"",address:d.address||"",market:d.market||"",type:d.type,paymentMethod:d.paymentMethod,paymentStatus:d.paymentStatus,amountPaid:d.amountPaid,subtotal:t.sub,discount:t.disc,net:t.net,cancelled:false,lines:lines.map(function(x){return {productId:x.p.id,reference:x.p.reference,name:x.p.name,quantity:x.q,unitPrice:x.price,unit:x.l.unit||"pièce",costUnit:n(x.p.unitCost)};})};
    S.invoices.push(inv);var totalLines=lines.reduce(function(a,x){return a+x.q*x.price;},0);
    lines.forEach(function(x){var gross=x.q*x.price,discountShare=totalLines?t.disc*gross/totalLines:0,rr=gross-discountShare,unitNet=x.q?rr/x.q:0,cc=n(x.p.unitCost);S.sales.push({id:uid(),date:inv.date,invoiceId:inv.id,invoiceNo:inv.number,client:inv.client,productId:x.p.id,reference:x.p.reference,name:x.p.name,quantity:x.q,unitPrice:unitNet,revenue:rr,costUnit:cc,costTotal:x.q*cc,grossProfit:rr-x.q*cc,paymentStatus:inv.paymentStatus,paymentMethod:inv.paymentMethod,paidAmount:t.net?inv.amountPaid*rr/t.net:0});});
    S.draft={id:uid(),number:invoiceNumber(today()),date:today(),due:"",client:"",phone:"",address:"",market:"",type:d.type||"Gros",paymentMethod:"Espèces",paymentStatus:"Impayé",amountPaid:0,discount:0,lines:[{productId:"",quantity:1,customPrice:"",unit:"pièce"}]};
    save();render();toast("Facture validée et vente enregistrée.");setTimeout(function(){printInvoice(inv);},300);
  }
  function printInvoice(inv){
    if(!inv)return;var rows=(inv.lines||[]).map(function(l){return "<tr><td>"+esc(l.reference)+"</td><td>"+esc(l.name)+"</td><td class=\"num\">"+fmt(l.quantity)+"</td><td class=\"num\">"+money(l.unitPrice)+"</td><td class=\"num\">"+money(n(l.quantity)*n(l.unitPrice))+"</td><td>"+esc(l.unit||"pièce")+"</td></tr>";}).join(""),s=S.settings;
    el("invoice-print").innerHTML='<div class="print-sheet"><div class="print-head"><div><h1>'+esc(s.companyName)+'</h1><p>'+esc(s.activity)+"<br>"+esc(s.address)+"<br>Tél. "+esc(s.phone)+" · "+esc(s.email)+"<br>NIF : "+esc(s.nif)+" · RC : "+esc(s.rc||"—")+" · NIS : "+esc(s.nis||"—")+'</p></div><div class="print-tag"><strong>FACTURE / فاتورة</strong><br>N° '+esc(inv.number)+"<br>Date : "+dateFmt(inv.date)+(inv.due?"<br>Échéance : "+dateFmt(inv.due):"")+"</div></div><h2 class=\"print-title\">Facture client</h2><div class=\"print-meta\"><span>Client / الزبون</span><strong>"+esc(inv.client||"—")+"</strong><span>Téléphone / الهاتف</span><strong>"+esc(inv.phone||"—")+"</strong><span>Adresse / العنوان</span><strong>"+esc(inv.address||"—")+"</strong><span>Marché / السوق</span><strong>"+esc(inv.market||"—")+"</strong><span>Type de prix</span><strong>"+esc(inv.type)+"</strong><span>Mode de paiement</span><strong>"+esc(inv.paymentMethod)+"</strong></div><table class=\"print-table\"><thead><tr><th>Référence</th><th>Désignation / المنتج</th><th class=\"num\">Quantité</th><th class=\"num\">Prix unitaire</th><th class=\"num\">Total</th><th>Unité</th></tr></thead><tbody>"+rows+'</tbody></table><div class="print-total"><div><span>Sous-total / المجموع</span><strong>'+money(inv.subtotal)+'</strong></div><div><span>Remise / التخفيض</span><strong>− '+money(inv.discount)+'</strong></div><div class="net"><span>NET À PAYER / الصافي للدفع</span><strong>'+money(inv.net)+'</strong></div><div><span>État du paiement</span><strong>'+esc(inv.paymentStatus)+'</strong></div></div><div class="print-foot"><span>Signature client / توقيع الزبون</span><span>Cachet et signature KABAMAN / ختم وإمضاء</span></div><p style="text-align:center;font-size:9px;color:#77899a;margin-top:35px">Merci pour votre confiance. / شكراً على ثقتكم.</p></div>';
    document.body.classList.add("print-mode");setTimeout(function(){window.print();},100);window.onafterprint=function(){document.body.classList.remove("print-mode");};
  }
  function openInvoice(id){
    var i=S.invoices.find(function(x){return x.id===id;});if(!i)return;
    var rows=i.lines.map(function(l){return "<tr><td>"+esc(l.reference)+"</td><td>"+esc(l.name)+'</td><td class="num">'+fmt(l.quantity)+'</td><td class="num">'+money(l.unitPrice)+'</td><td class="num">'+money(n(l.quantity)*n(l.unitPrice))+"</td></tr>";}).join("");
    var body='<div class="invoice-brand-row"><div><strong>'+esc(S.settings.companyName)+'</strong><div class="product-ref">'+esc(S.settings.address)+" · "+esc(S.settings.phone)+'</div></div><span>'+esc(i.number)+'</span></div><div class="mini-meta"><span>Date</span><strong>'+dateFmt(i.date)+'</strong><span>Client</span><strong>'+esc(i.client||"—")+'</strong><span>Paiement</span><strong>'+esc(i.paymentStatus)+" · "+esc(i.paymentMethod)+'</strong><span>Type</span><strong>'+esc(i.type)+'</strong></div><div class="table-scroll"><table><thead><tr><th>Référence</th><th>Produit</th><th class="num">Qté</th><th class="num">Prix unit.</th><th class="num">Total</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="calc-summary" style="margin-top:12px">'+calcLine("Sous-total",money(i.subtotal))+calcLine("Remise","− "+money(i.discount))+calcLine("Net à payer",money(i.net),true)+"</div>";
    modal("Facture "+i.number,body,'<button class="button button-outline" data-action="close-modal">Fermer</button><button class="button button-primary" data-action="print-invoice" data-id="'+i.id+'">Imprimer</button>');
  }
  function cancelInvoice(id){var i=S.invoices.find(function(x){return x.id===id;});if(!i||i.cancelled)return;if(!confirm("Annuler la facture "+i.number+" ? Elle sera exclue du stock et des rapports."))return;i.cancelled=true;save();render();toast("Facture annulée.");}

  function salesPage(){
    var d=S.saleDraft,p=product(d.productId),unit=p?(d.priceMode==="Gros"?p.wholesalePrice:d.priceMode==="Négocié"?(d.customPrice||p.negotiatedPrice):p.retailPrice):0;
    var prodOpts='<option value="">Choisir un produit…</option>'+S.products.map(function(x){return '<option value="'+x.id+'"'+(x.id===d.productId?" selected":"")+'>'+esc(x.reference+" · "+x.name+" · stock "+fmt(stock(x)))+"</option>";}).join("");
    var form=S.products.length?'<div class="form-grid four"><div class="field"><label>Date</label><input class="input" type="date" data-sale="date" value="'+esc(d.date)+'"></div><div class="field"><label>Produit</label><select class="select" data-sale="productId">'+prodOpts+"</select></div>"+inputField("Client","sale.client",d.client,"Nom du client")+inputField("N° facture facultatif","sale.invoiceNo",d.invoiceNo,"Référence facture")+'<div class="field"><label>Quantité</label><input class="input" type="number" min="1" data-sale="quantity" value="'+esc(d.quantity)+'"></div>'+selectField("Type de prix","sale.priceMode",d.priceMode,[["Gros","Gros"],["Détail","Détail"],["Négocié","Négocié"]])+(d.priceMode==="Négocié"?'<div class="field"><label>Prix convenu / pièce</label><input class="input" type="number" min="0" data-sale="customPrice" value="'+esc(d.customPrice||(p?p.negotiatedPrice:""))+'"></div>':'<div class="field"><label>Prix unitaire</label><input class="input" readonly value="'+esc(unit)+'"></div>')+selectField("État du paiement","sale.paymentStatus",d.paymentStatus,["Payé","Partiellement payé","Impayé"])+selectField("Mode de paiement","sale.paymentMethod",d.paymentMethod,["Espèces","Virement","Autre"])+'<div class="field" style="align-self:end"><button class="button button-primary w-full" data-action="save-sale">Enregistrer</button></div></div>'+(p?'<div class="notice '+(n(d.quantity)>stock(p)?"warning":"")+'" style="margin-top:13px">Stock disponible : <strong>'+fmt(stock(p))+"</strong> pièce(s). Prix sélectionné : <strong>"+money(unit)+"</strong>."+(n(d.quantity)>stock(p)?" La quantité demandée dépasse le stock.":"")+"</div>":""):'<div class="notice warning">Ajoute un produit au catalogue avant de saisir une vente.</div>';
    var ss=liveSales().slice().sort(function(a,b){return String(b.date).localeCompare(String(a.date));}),q=(S.salesSearch||"").toLowerCase(),filter=S.salesStatusFilter||"Tous";
    if(q)ss=ss.filter(function(x){return [x.name,x.reference,x.client,x.invoiceNo].join(" ").toLowerCase().indexOf(q)>=0;});if(filter!=="Tous")ss=ss.filter(function(x){return x.paymentStatus===filter;});
    var rows=ss.map(function(s){return '<tr><td>'+dateFmt(s.date)+'</td><td><div class="product-name">'+esc(s.client||"Vente directe")+'</div><div class="product-ref">'+esc(s.invoiceNo||"Sans facture")+'</div></td><td><div class="product-name">'+esc(s.name)+'</div><div class="product-ref">'+esc(s.reference)+'</div></td><td class="num">'+fmt(s.quantity)+'</td><td class="num">'+money(s.unitPrice)+'</td><td class="num">'+money(rev(s))+'</td><td class="num">'+money(profit(s))+'</td><td><span class="status-pill '+statusClass(s.paymentStatus)+'">'+esc(s.paymentStatus||"Impayé")+'</span></td><td>'+(s.invoiceId?'<span class="muted tiny">Facture</span>':'<button class="button button-icon" data-del-sale="'+s.id+'">×</button>')+"</td></tr>";}).join("");
    var all=liveSales();
    return header("JOURNAL COMMERCIAL","Ventes","Enregistre les ventes directes et retrouve celles créées depuis une facture.",'<button class="button button-outline" data-action="export-sales">⇩ Exporter l’historique</button>')+
      '<div class="grid stats-grid">'+stat("Lignes de vente",fmt(all.length),"Ventes actives","↗","blue")+stat("Chiffre d’affaires",money(all.reduce(function(a,s){return a+rev(s);},0)),"Depuis le début du suivi","◈","teal")+stat("Bénéfice brut",money(all.reduce(function(a,s){return a+profit(s);},0)),"CA moins coûts produits","＋","gold")+stat("Quantités vendues",fmt(all.reduce(function(a,s){return a+n(s.quantity);},0)),"Pièces enregistrées","▦","red")+"</div>"+
      '<section class="card card-pad">'+cardHead("Enregistrer une vente","Le stock est mis à jour dès l’enregistrement.")+form+"</section>"+
      '<section class="card table-card" style="margin-top:16px"><div class="card-pad flex-between"><div><h2>Historique des ventes</h2><p class="page-subtitle">Le coût est conservé selon sa valeur au moment de la vente.</p></div>'+
      '<div class="filter-row"><div class="search-box"><span>⌕</span><input class="input" id="sales-search" value="'+esc(S.salesSearch||"")+'" placeholder="Client, produit, facture"></div>'+
      '<select class="select" id="sales-filter"><option'+(filter==="Tous"?" selected":"")+'>Tous</option><option'+(filter==="Payé"?" selected":"")+'>Payé</option><option'+(filter==="Partiellement payé"?" selected":"")+'>Partiellement payé</option><option'+(filter==="Impayé"?" selected":"")+'>Impayé</option></select></div></div>'+
      (rows?'<div class="table-scroll"><table><thead><tr><th>Date</th><th>Client / facture</th><th>Produit</th><th class="num">Qté</th><th class="num">Prix unit.</th><th class="num">CA</th><th class="num">Bénéfice</th><th>Paiement</th><th></th></tr></thead><tbody>'+rows+"</tbody></table></div>":'<div class="empty-state"><strong>Aucune vente correspondante</strong>Enregistre une vente ou modifie les filtres.</div>')+"</section>";
  }
  function saveSale(){
    var d=S.saleDraft,p=product(d.productId),q=n(d.quantity);if(!p){toast("Choisis un produit du catalogue.",true);return;}if(q<=0){toast("La quantité doit être supérieure à zéro.",true);return;}
    var price=d.priceMode==="Gros"?n(p.wholesalePrice):d.priceMode==="Négocié"?n(d.customPrice||p.negotiatedPrice):n(p.retailPrice);if(price<=0){toast("Le prix de vente doit être supérieur à zéro.",true);return;}
    var rr=q*price,cc=q*n(p.unitCost);S.sales.push({id:uid(),date:d.date||today(),invoiceNo:d.invoiceNo||"",client:d.client||"",productId:p.id,reference:p.reference,name:p.name,quantity:q,unitPrice:price,revenue:rr,costUnit:n(p.unitCost),costTotal:cc,grossProfit:rr-cc,paymentStatus:d.paymentStatus,paymentMethod:d.paymentMethod,paidAmount:d.paymentStatus==="Payé"?rr:0});
    S.saleDraft={date:today(),productId:"",quantity:1,priceMode:"Détail",customPrice:"",client:"",invoiceNo:"",paymentStatus:"Payé",paymentMethod:"Espèces"};save();render();toast("Vente enregistrée et stock actualisé.");
  }
  function deleteSale(id){var s=S.sales.find(function(x){return x.id===id;});if(!s||s.invoiceId)return;if(!confirm("Supprimer cette vente ? Le stock sera recalculé."))return;S.sales=S.sales.filter(function(x){return x.id!==id;});save();render();toast("Vente supprimée.");}
  function exportSales(){var lines=[["date","numero_facture","client","reference","designation","quantite","prix_unitaire_DA","chiffre_affaires_DA","cout_unitaire_DA","cout_total_DA","benefice_brut_DA","paiement"].join(";")];liveSales().forEach(function(s){lines.push([s.date,s.invoiceNo,s.client,s.reference,s.name,s.quantity,s.unitPrice,rev(s),s.costUnit,cost(s),profit(s),s.paymentStatus].map(csvVal).join(";"));});download("kabaman_ventes_"+today()+".csv","\ufeff"+lines.join("\r\n"),"text/csv;charset=utf-8");}

  function analytics(){
    var period=S.analyticsPeriod||"month",now=new Date(),month=today().slice(0,7),ss=liveSales().filter(function(s){var d=String(s.date||"");if(period==="month")return d.slice(0,7)===month;if(period==="year")return d.slice(0,4)===String(now.getFullYear());if(period==="quarter"){var start=new Date(now.getFullYear(),now.getMonth()-2,1);return d>=start.getFullYear()+"-"+String(start.getMonth()+1).padStart(2,"0")+"-01"&&d.slice(0,7)<=month;}return true;});
    var rr=ss.reduce(function(a,s){return a+rev(s);},0),cc=ss.reduce(function(a,s){return a+cost(s);},0),pp=rr-cc,qty=ss.reduce(function(a,s){return a+n(s.quantity);},0),margin=rr?pp/rr*100:0,map={};
    ss.forEach(function(s){var k=s.productId||s.reference||s.name;if(!map[k])map[k]={name:s.name,ref:s.reference,revenue:0,cost:0,profit:0,qty:0};map[k].revenue+=rev(s);map[k].cost+=cost(s);map[k].profit+=profit(s);map[k].qty+=n(s.quantity);});
    var ps=Object.keys(map).map(function(k){return map[k];}).sort(function(a,b){return b.profit-a.profit;}),max=Math.max.apply(null,ps.map(function(p){return p.profit;}).concat([1]));
    var bars=ps.slice(0,7).map(function(p){return '<div class="bar-row"><div class="bar-label">'+esc(p.name)+'</div><div class="bar-track"><div class="bar-fill" style="width:'+Math.max(0,Math.min(100,p.profit/max*100))+'%"></div></div><div class="bar-value">'+money(p.profit)+"</div></div>";}).join("");
    var rows=ps.map(function(p){return '<tr><td><div class="product-name">'+esc(p.name)+'</div><div class="product-ref">'+esc(p.ref)+'</div></td><td class="num">'+fmt(p.qty)+'</td><td class="num">'+money(p.revenue)+'</td><td class="num">'+money(p.cost)+'</td><td class="num strong">'+money(p.profit)+"</td></tr>";}).join("");
    var ms=months(6),vals=monthValues(ms,liveSales());
    return header("ANALYSE","Rentabilité","Chiffre d’affaires, coûts et bénéfice brut par période.",'<select class="select" id="period-select" style="width:auto">'+options(period,[["month","Ce mois"],["quarter","3 derniers mois"],["year","Cette année"],["all","Tout l’historique"]])+"</select>")+
    '<div class="grid stats-grid">'+stat("Chiffre d’affaires",money(rr),"Ventes sur la période","↗","blue")+stat("Coût des produits vendus",money(cc),"Coût enregistré à la vente","▦","gold")+stat("Bénéfice brut",money(pp),"Chiffre d’affaires − coûts","◈","teal")+stat("Taux de marge brute",fmt(margin,1)+"%","Bénéfice / chiffre d’affaires","%","red")+"</div>"+
    '<div class="summary-kpis"><div class="summary-kpi"><span>Pièces vendues</span><strong>'+fmt(qty)+'</strong></div><div class="summary-kpi"><span>Lignes de vente</span><strong>'+fmt(ss.length)+'</strong></div><div class="summary-kpi"><span>Références vendues</span><strong>'+fmt(ps.length)+"</strong></div></div>"+
    '<div class="grid analysis-grid"><section class="card card-pad">'+cardHead("Ventes mensuelles","Chiffre d’affaires des six derniers mois")+(liveSales().length?chart(ms,vals):'<div class="empty-state">Les résultats apparaîtront après les premières ventes.</div>')+"</section><section class=\"card card-pad\">"+cardHead("Bénéfice par produit","Produits les plus rentables")+(bars||'<div class="empty-state">Aucune vente sur cette période.</div>')+"</section></div>"+
    '<section class="card table-card">'+cardHead("Détail par produit","Le bénéfice brut ne déduit pas les charges fixes.")+(rows?'<div class="table-scroll"><table><thead><tr><th>Produit</th><th class="num">Qté vendue</th><th class="num">Chiffre d’affaires</th><th class="num">Coût total</th><th class="num">Bénéfice brut</th></tr></thead><tbody>'+rows+"</tbody></table></div>":'<div class="empty-state"><strong>Aucune donnée</strong>Enregistre des ventes pour analyser la rentabilité.</div>')+"</section>";
  }
  function settingsPage(){
    var s=S.settings;
    return header("CONFIGURATION","Paramètres","Taux des calculs et coordonnées affichées sur les factures.",'<button class="button button-primary" data-action="save-settings">Enregistrer les paramètres</button>')+
    '<div class="setting-layout"><section class="card card-pad">'+cardHead("Taux et charges","Valeurs initiales reprises des classeurs.")+'<div class="form-grid two">'+moneyField("Majoration de gros","settings.wholesaleMarkup",s.wholesaleMarkup,"%","0.1",0)+moneyField("Majoration de détail","settings.retailMarkup",s.retailMarkup,"%","0.1",0)+moneyField("Taux douanier estimatif","settings.customsRate",s.customsRate,"%","0.1",0)+moneyField("Frais bancaires","settings.bankRate",s.bankRate,"%","0.1",0)+moneyField("CASNOS mensuel","settings.casnosMonthly",s.casnosMonthly,"DA","100",0)+moneyField("Impôt fixe si activité = Non","settings.taxFixedMonthly",s.taxFixedMonthly,"DA","100",0)+moneyField("Impôt si activité = Oui","settings.taxActivityRate",s.taxActivityRate,"% du CA","0.1",0)+moneyField("Taux EUR → DZD","settings.eurToDzd",s.eurToDzd,"DA / EUR","1",0)+moneyField("Alerte de stock","settings.stockAlert",s.stockAlert,"pièces","1",0)+'</div><div class="divider"></div><div class="notice warning">Les taux et charges sont des hypothèses reprises des fichiers source. Vérifie leur validité avant chaque import.</div></section>'+
    '<section class="card card-pad">'+cardHead("Coordonnées de l’entreprise","Ces informations apparaissent sur les factures imprimées.")+'<div class="form-grid two">'+inputField("Nom de l’entreprise","settings.companyName",s.companyName,"KABAMAN")+inputField("Activité / sous-titre","settings.activity",s.activity,"Commerce")+inputField("Adresse","settings.address",s.address,"Adresse professionnelle","field-wide")+inputField("Téléphone","settings.phone",s.phone,"Téléphone")+inputField("E-mail","settings.email",s.email,"Adresse e-mail")+inputField("NIF","settings.nif",s.nif,"Numéro fiscal")+inputField("RC","settings.rc",s.rc,"Registre de commerce")+inputField("NIS","settings.nis",s.nis,"Numéro statistique")+'</div><div class="divider"></div><div class="notice">Catalogue, factures et ventes sont conservés dans ce navigateur. Télécharge régulièrement une sauvegarde JSON.</div></section></div><section class="card card-pad" style="margin-top:16px">'+cardHead("Sauvegarde","Exporte ou restaure toutes les données.")+'<div class="toolbar"><button class="button button-outline" data-action="backup">⇩ Télécharger une sauvegarde JSON</button><button class="button button-outline" data-action="restore">⇧ Restaurer une sauvegarde JSON</button><span class="muted tiny">Produits, factures, ventes et paramètres</span></div><input id="backup-file" type="file" accept=".json,application/json" hidden></section>';
  }
  function backup(){var copy=JSON.parse(JSON.stringify(S));delete copy.activePage;delete copy.catalogSearch;delete copy.salesSearch;delete copy.salesStatusFilter;download("kabaman_sauvegarde_"+today()+".json",JSON.stringify({app:"KABAMAN Gestion",version:1,exportedAt:new Date().toISOString(),data:copy},null,2),"application/json");toast("Sauvegarde téléchargée.");}
  function restore(file){if(!file)return;var rd=new FileReader();rd.onload=function(){try{var data=JSON.parse(rd.result||"{}");if(!confirm("Restaurer cette sauvegarde ? Les données actuelles seront remplacées."))return;S=normalize(data.data||data);ensureDraft();save();go("dashboard");toast("Sauvegarde restaurée.");}catch(e){toast("Fichier de sauvegarde illisible.",true);}};rd.readAsText(file);}

  function draftInvoiceForPrint(){var d=S.draft,t=totals(d);return {id:d.id,number:d.number,date:d.date,due:d.due,client:d.client,phone:d.phone,address:d.address,market:d.market,type:d.type,paymentMethod:d.paymentMethod,paymentStatus:d.paymentStatus,subtotal:t.sub,discount:t.disc,net:t.net,lines:d.lines.map(function(l){var p=product(l.productId);return p?{reference:p.reference,name:p.name,quantity:n(l.quantity),unitPrice:linePrice(l,d.type),unit:l.unit||"pièce"}:null;}).filter(Boolean)};}
  function addInvoiceLine(){S.draft.lines.push({productId:"",quantity:1,customPrice:"",unit:"pièce"});save();render();}
  function resetDraft(){S.draft={id:uid(),number:invoiceNumber(today()),date:today(),due:"",client:"",phone:"",address:"",market:"",type:"Gros",paymentMethod:"Espèces",paymentStatus:"Impayé",amountPaid:0,discount:0,lines:[{productId:"",quantity:1,customPrice:"",unit:"pièce"}]};save();render();}

  function act(name,target){
    if(name==="new-product")productModal("");else if(name==="save-product")saveProduct();else if(name==="close-modal")el("modal-root").innerHTML="";
    else if(name==="export-catalog")exportCatalog();else if(name==="import-csv")el("csv-file").click();
    else if(name==="add-calc"){if(S.multi.lines.length>=100){toast("Maximum : 100 lignes.",true);return;}S.multi.lines.push({reference:"",name:"",quantity:"",buyPrice:"",currency:"DA"});save();render();}
    else if(name==="save-multi")addProducts(calcMulti().rows.map(function(x){return {reference:x.src.reference,name:x.src.name,q:x.q,unitCost:x.unitCost,wholesale:x.wholesale,retail:x.retail};}));
    else if(name==="save-single"){var r=calcSingle(),c=S.single;addProducts([{reference:c.reference,name:c.name,q:r.q,unitCost:r.unitCost,wholesale:r.wholesale,retail:r.retail}]);}
    else if(name==="add-inv-line")addInvoiceLine();else if(name==="save-invoice")saveInvoice();else if(name==="new-invoice")resetDraft();
    else if(name==="print-draft")printInvoice(draftInvoiceForPrint());else if(name==="print-invoice"){var inv=S.invoices.find(function(i){return i.id===target.dataset.id;});el("modal-root").innerHTML="";printInvoice(inv);}
    else if(name==="save-sale")saveSale();else if(name==="export-sales")exportSales();
    else if(name==="save-settings"){save();toast("Paramètres enregistrés.");}
    else if(name==="backup")backup();else if(name==="restore")el("backup-file").click();
  }
  document.addEventListener("click",function(e){
    var pg=e.target.closest("[data-page]");if(pg){go(pg.dataset.page);return;}var jump=e.target.closest("[data-go]");if(jump){go(jump.dataset.go);return;}
    var mode=e.target.closest("[data-calc-mode]");if(mode){S.calcMode=mode.dataset.calcMode;save();render();return;}
    var a=e.target.closest("[data-action]");if(a){act(a.dataset.action,a);return;}
    var edit=e.target.closest("[data-edit]");if(edit){productModal(edit.dataset.edit);return;}var del=e.target.closest("[data-delete]");if(del){removeProduct(del.dataset.delete);return;}
    var rm=e.target.closest("[data-remove-calc]");if(rm){if(S.multi.lines.length>1){S.multi.lines.splice(n(rm.dataset.removeCalc),1);save();render();}else toast("Garde au moins une ligne.",true);return;}
    var rmi=e.target.closest("[data-rm-inv]");if(rmi){if(S.draft.lines.length>1){S.draft.lines.splice(n(rmi.dataset.rmInv),1);save();render();}else toast("Garde au moins une ligne.",true);return;}
    var oi=e.target.closest("[data-open-inv]");if(oi){openInvoice(oi.dataset.openInv);return;}var ci=e.target.closest("[data-cancel-inv]");if(ci){cancelInvoice(ci.dataset.cancelInv);return;}
    var ds=e.target.closest("[data-del-sale]");if(ds){deleteSale(ds.dataset.delSale);return;}
    if(e.target.matches("[data-backdrop]"))el("modal-root").innerHTML="";
  });
  document.addEventListener("input",function(e){
    var t=e.target;
    if(t.matches("[data-bind]")){var path=t.dataset.bind,val=t.type==="number"?(t.value===""?"":n(t.value)):t.value;var key=path.split(".").pop(),group=path.split(".")[0];if(group==="settings")S.settings[key]=val;else if(group==="multi")S.multi[key]=val;else if(group==="single")S.single[key]=val;else if(group==="draft")S.draft[key]=val;else if(group==="sale")S.saleDraft[key]=val;save();if(group==="multi"||group==="single"){updateCalc();}else if(group==="draft"){updateDraft();}else if(group==="sale"&&(key==="productId"||key==="priceMode")){render();}return;}
    if(t.matches("[data-multi]")){var bits=t.dataset.multi.split("|");if(S.multi.lines[n(bits[0])])S.multi.lines[n(bits[0])][bits[1]]=t.value;updateCalc();return;}
    if(t.matches("[data-draft]")){S.draft[t.dataset.draft]=t.value;updateDraft();return;}
    if(t.matches("[data-invline]")){var p=t.dataset.invline.split("|");if(S.draft.lines[n(p[0])])S.draft.lines[n(p[0])][p[1]]=t.value;updateDraft();return;}
    if(t.matches("[data-sale]")){S.saleDraft[t.dataset.sale]=t.value;save();if(t.dataset.sale==="productId"||t.dataset.sale==="priceMode"){render();return;}return;}
    if(t.id==="catalog-search"||t.id==="sales-search"){var id=t.id;S[id==="catalog-search"?"catalogSearch":"salesSearch"]=t.value;save();var pos=t.selectionStart;render();var again=el(id);if(again){again.focus();again.setSelectionRange(pos,pos);}}
  });
  document.addEventListener("change",function(e){
    var t=e.target;
    if(t.matches("[data-bind]")){var path=t.dataset.bind,group=path.split(".")[0],key=path.split(".").pop(),val=t.type==="number"?(t.value===""?"":n(t.value)):t.value;if(group==="settings")S.settings[key]=val;else if(group==="multi")S.multi[key]=val;else if(group==="single")S.single[key]=val;else if(group==="draft"){S.draft[key]=val;if(key==="paymentStatus"){var net=totals(S.draft).net;if(val==="Payé")S.draft.amountPaid=net;if(val==="Impayé")S.draft.amountPaid=0;}if(key==="type"&&val==="Négocié")S.draft.lines.forEach(function(l){var p=product(l.productId);if(p&&!l.customPrice)l.customPrice=p.negotiatedPrice;});render();return;}else if(group==="sale"){S.saleDraft[key]=val;if(key==="priceMode"&&val==="Négocié"&&!S.saleDraft.customPrice){var p0=product(S.saleDraft.productId);if(p0)S.saleDraft.customPrice=p0.negotiatedPrice;}if(key==="productId"||key==="priceMode"){save();render();return;}}save();if(group==="multi"||group==="single")updateCalc();return;}
    if(t.matches("[data-multi]")){var b=t.dataset.multi.split("|");if(S.multi.lines[n(b[0])])S.multi.lines[n(b[0])][b[1]]=t.value;updateCalc();return;}
    if(t.matches("[data-draft]")){S.draft[t.dataset.draft]=t.value;updateDraft();return;}
    if(t.matches("[data-invline]")){var x=t.dataset.invline.split("|"),line=S.draft.lines[n(x[0])];if(line){line[x[1]]=t.value;if(x[1]==="productId"&&S.draft.type==="Négocié"){var p1=product(t.value);line.customPrice=p1?p1.negotiatedPrice:"";}}save();render();return;}
    if(t.matches("[data-sale]")){S.saleDraft[t.dataset.sale]=t.value;save();if(t.dataset.sale==="productId"||t.dataset.sale==="priceMode")render();return;}
    if(t.id==="period-select"){S.analyticsPeriod=t.value;save();render();return;}
    if(t.id==="sales-filter"){S.salesStatusFilter=t.value;save();render();return;}
    if(t.id==="csv-file"){importCSV(t.files[0]);t.value="";return;}
    if(t.id==="backup-file"||t.id==="restore-file"){restore(t.files[0]);t.value="";}
  });
  function start(){if(!pageNames[S.activePage])S.activePage="dashboard";ensureDraft();text("year-now",new Date().getFullYear());text("page-crumb",pageNames[S.activePage]);try{text("today-chip",new Intl.DateTimeFormat("fr-FR",{weekday:"short",day:"numeric",month:"short"}).format(new Date()));}catch(e){}document.querySelectorAll(".nav-item").forEach(function(b){b.classList.toggle("active",b.dataset.page===S.activePage);});el("backup-button").addEventListener("click",backup);el("restore-button").addEventListener("click",function(){el("restore-file").click();});render();save();}
  start();
}());

